import {arxivMetadata} from './arxiv-metadata.mjs';
import {validateSavedLiteratureAiResults} from './literature-ai-model.mjs';
import {normalizeLiteratureGroups} from './literature-groups.mjs';
export const literatureTypes=Object.freeze({generic:'通用文献',thesis:'学位论文',journal:'期刊文章',conference:'会议论文',book:'图书',patent:'专利',standard:'标准',yearbook:'年鉴',newspaper:'报纸',report:'研究报告',chapter:'图书章节',preprint:'预印本'});
export function literatureBibliography(input={}){
 const documentType=input.documentType||'generic';if(!Object.hasOwn(literatureTypes,documentType))throw Error('请选择支持的文献类型。');
 const output={documentType};for(const [key,label,max] of [['journal','刊名',500],['publisher','出版机构',500],['abstract','摘要',20000],['publicationSource','刊物来源',300],['volume','卷号',100],['issue','期号',100],['pages','页码',100],['group','分组',80]]){if(input[key]!==undefined&&typeof input[key]!=='string')throw Error(label+'格式无效。');const value=String(input[key]||'').trim();if(value.length>max)throw Error(label+'最多 '+max.toLocaleString('zh-CN')+' 字符。');output[key]=value;}
 if(input.keywords!==undefined&&input.keywords!==null&&typeof input.keywords!=='string'&&!Array.isArray(input.keywords))throw Error('关键词格式无效。');const raw=Array.isArray(input.keywords)?input.keywords:String(input.keywords||'').split(/[;；\n]/);if(raw.some(v=>typeof v!=='string'))throw Error('关键词格式无效。');const keywords=[...new Set(raw.map(v=>v.trim()).filter(Boolean))];if(keywords.length>20||keywords.some(v=>v.length>80))throw Error('最多填写 20 个关键词，每个不超过 80 字符，以分号分隔。');return {...output,keywords};
}
function originalDocumentReference(input){const originalFileId=String(input.originalFileId||''),originalOwnerId=String(input.originalOwnerId||'');if((originalFileId||originalOwnerId)&&(!/^[A-Za-z0-9_-]{1,160}$/.test(originalFileId)||!/^[A-Za-z0-9_-]{1,160}$/.test(originalOwnerId)))throw Error('上传原件的归属信息无效，请重新导入原件。');return {originalFileId,originalOwnerId};}
export const literatureKey='paperknow-literature';
export const readingStates=[['all','全部'],['unread','待读'],['reading','阅读中'],['read','已读']];
export const scopes={full:'已有正文',abstract:'仅摘要',metadata:'仅元数据'};
export function validatePaper(input){const text=String(input.text||'').trim(),scope=Object.hasOwn(scopes,input.scope)?input.scope:'metadata',title=String(input.title||'').trim();if(!title||title.length>300)throw Error('请填写不超过 300 字符的文献标题。');if(text.length>200000)throw Error('正文最多 200,000 字符，请按章节导入。');if(scope!=='metadata'&&!text)throw Error('请选择仅元数据，或提供对应的正文 / 摘要。');let url=input.source==='arxiv'?arxivMetadata(input).url:String(input.url||'').trim();if(url){try{const parsed=new URL(url);if(!['https:','http:'].includes(parsed.protocol))throw Error();url=parsed.href;}catch{throw Error('来源链接仅支持有效的 HTTP / HTTPS 地址。');}}const year=String(input.year||'').trim();if(year&&!/^\d{4}$/.test(year))throw Error('年份请填写四位数字，或留空。');const doi=String(input.doi||'').trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'');if(doi&&!/^10\.\d{4,9}\/\S+$/i.test(doi))throw Error('DOI 格式应类似 10.1234/example；当前不联网核验。');const notes=Array.isArray(input.notes)?input.notes:[];if(notes.length>100)throw Error('每篇文献最多保留 100 条笔记。');return {...input,...arxivMetadata(input),...literatureBibliography(input),...originalDocumentReference(input),aiResults:validateSavedLiteratureAiResults(input.aiResults),title,authors:String(input.authors||'').slice(0,1000),year,doi,url,scope,text:scope==='metadata'?'':text,tags:[...new Set((Array.isArray(input.tags)?input.tags:String(input.tags||'').split(/[，,]/)).map(t=>String(t).trim()).filter(Boolean))].slice(0,12).map(t=>t.slice(0,40)),projectId:String(input.projectId||''),status:['unread','reading','read'].includes(input.status)?input.status:'unread',fileName:String(input.fileName||'').slice(0,300),warnings:(Array.isArray(input.warnings)?input.warnings:[]).map(String).slice(0,20),notes:notes.map(n=>{if(!n||typeof n.id!=='string'||!String(n.text||'').trim()||String(n.text).length>5000)throw Error('笔记格式无效或超过 5,000 字符。');return {id:n.id,text:String(n.text),location:String(n.location||'').slice(0,300),createdAt:String(n.createdAt||''),updatedAt:String(n.updatedAt||n.createdAt||'')};})};}
export function selectLiterature(papers,{status='all',project='all',tag='all',group='all',query='',sort='added'}={},projects=[]){const names=new Map(projects.map(p=>[p.id,p.name]));const q=query.trim().toLocaleLowerCase();return papers.filter(p=>(status==='all'||p.status===status)&&(project==='all'||(project==='none'?!p.projectId:p.projectId===project))&&(tag==='all'||p.tags.includes(tag))&&(group==='all'||(group==='none'?!p.group:p.group===group.replace(/^group:/,'')))&&(!q||[p.title,p.authors,p.doi,p.year,p.journal,p.publisher,p.publicationSource,p.group,...(p.keywords||[]),p.arxivId||'',p.sourceId||'',...(p.categories||[]),names.get(p.projectId)||'',...p.tags].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>sort==='title'?a.title.localeCompare(b.title,'zh-CN'):sort==='read'?(Date.parse(b.lastReadAt)||0)-(Date.parse(a.lastReadAt)||0):(Date.parse(b.createdAt)||0)-(Date.parse(a.createdAt)||0));}
export function mergeLiteratureBackup(existing,backup,existingGroups=[]){if(backup?.format!=='paperknow-literature-backup'||backup.version!==1||!Array.isArray(backup.papers)||backup.papers.length>200)throw Error('请选择 PaperKnow 文献备份 JSON（最多 200 篇）。');const ids=new Set(existing.map(p=>p.id));const added=[];for(const raw of backup.papers){if(typeof raw.id!=='string'||!raw.id||raw.id.length>200)throw Error('备份中的文献编号无效。');const paper=validatePaper(raw);if(!ids.has(paper.id)){added.push(paper);ids.add(paper.id);}}if(existing.length+added.length>200)throw Error('文献库最多保存 200 篇，请先备份。');return {papers:[...existing,...added],groups:normalizeLiteratureGroups([...existingGroups,...normalizeLiteratureGroups(backup.groups||[]),...[...existing,...added].map(p=>p.group).filter(Boolean)]),added:added.length,skipped:backup.papers.length-added.length};}
export function markOpened(paper,now=new Date().toISOString()){return {...paper,lastReadAt:now};}
